async getSlots(): Promise<ResourceSlotsDto[]> {
  const data = await this.getSlotsData();
  const maps = this.createSlotsMaps(data);

  return this.buildResourceSlots(data, maps);
}

private async getSlotsData(): Promise<SlotsData> {
  const [resources, slots, dependencies] = await Promise.all([
    this.manager.find(Resource, { order: { id: 'ASC' } }),
    this.manager.find(Slot, { order: { id: 'ASC' } }),
    this.manager.find(BlockingDependency),
  ]);

  return { resources, slots, dependencies };
}

private createSlotsMaps({ slots, dependencies }: SlotsData): SlotsMaps {
  const slotsByResourceId = new Map<number, Slot[]>();
  const blockingIdsByBlockedId = new Map<number, number[]>();
  const blockedIdsByBlockingId = new Map<number, number[]>();

  for (const slot of slots) {
    this.addToMapList(slotsByResourceId, slot.resourceId, slot);
  }

  for (const resourceSlots of slotsByResourceId.values()) {
    resourceSlots.sort((a, b) => this.toTime(a.start) - this.toTime(b.start));
  }

  for (const { blockedResourceId, blockingResourceId } of dependencies) {
    this.addToMapList(
      blockingIdsByBlockedId,
      blockedResourceId,
      blockingResourceId,
    );
    this.addToMapList(
      blockedIdsByBlockingId,
      blockingResourceId,
      blockedResourceId,
    );
  }

  return { slotsByResourceId, blockingIdsByBlockedId, blockedIdsByBlockingId };
}

private buildResourceSlots(
  { resources, slots }: SlotsData,
  maps: SlotsMaps,
): ResourceSlotsDto[] {
  const resourcesById = new Map<number, ResourceSlotsDto>();

  for (const resource of resources) {
    resourcesById.set(resource.id, { resourceId: resource.id, slots: [] });
  }

  for (const slot of slots) {
    const conflicts = this.findConflicts(slot, maps);
    const resourceIds = [
      slot.resourceId,
      ...(maps.blockedIdsByBlockingId.get(slot.resourceId) ?? []),
    ];

    for (const resourceId of resourceIds) {
      resourcesById.get(resourceId)?.slots.push({ ...slot, conflicts });
    }
  }

  return [...resourcesById.values()];
}

private findConflicts(
  slot: Slot,
  { slotsByResourceId, blockingIdsByBlockedId }: SlotsMaps,
): Slot[] {
  const resourceIds = [
    slot.resourceId,
    ...(blockingIdsByBlockedId.get(slot.resourceId) ?? []),
  ];
  const conflicts: Slot[] = [];

  for (const resourceId of resourceIds) {
    for (const other of slotsByResourceId.get(resourceId) ?? []) {
      if (this.toTime(other.start) >= this.toTime(slot.end)) {
        break;
      }

      if (
        other.id !== slot.id &&
        this.toTime(other.end) > this.toTime(slot.start)
      ) {
        conflicts.push(other);
      }
    }
  }

  return conflicts;
}

private addToMapList<T>(map: Map<number, T[]>, key: number, value: T) {
  const list = map.get(key) ?? [];
  list.push(value);
  map.set(key, list);
}

private toTime(date: string): number {
  return new Date(date).getTime();
}

